import{f as a,o,c as s,a2 as n}from"./chunks/framework.BtbFyp-E.js";const m=JSON.parse('{"title":"Guía de redacción de los anexos de la Especificación de Alcance CoopApps","description":"","frontmatter":{},"headers":[],"relativePath":"especificacion/_GUIA-REDACCION-ANEXOS.md","filePath":"especificacion/_GUIA-REDACCION-ANEXOS.md","lastUpdated":null}'),t={name:"especificacion/_GUIA-REDACCION-ANEXOS.md"};function d(r,e,i,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="guia-de-redaccion-de-los-anexos-de-la-especificacion-de-alcance-coopapps" tabindex="-1">Guía de redacción de los anexos de la Especificación de Alcance CoopApps <a class="header-anchor" href="#guia-de-redaccion-de-los-anexos-de-la-especificacion-de-alcance-coopapps" aria-label="Permalink to &quot;Guía de redacción de los anexos de la Especificación de Alcance CoopApps&quot;">​</a></h1><p>Versión 1.1 — 19/11/2026 (stack GoodApps: DEC-110–113, DEC-117; ver <code>06-impacto-adaptacion-stack-goodapps.md</code>). Documento de control interno para quien redacte o actualice cualquier anexo. Es obligatorio leerlo completo antes de escribir.</p><h2 id="_1-que-es-esta-especificacion" tabindex="-1">1. Qué es esta especificación <a class="header-anchor" href="#_1-que-es-esta-especificacion" aria-label="Permalink to &quot;1. Qué es esta especificación&quot;">​</a></h2><p>Es la especificación de alcance <strong>única y vigente</strong> del sistema SaaS multitenant para cooperativas de servicios. <strong>CoopApps</strong> es la marca comercial del producto (DEC-109); <strong>GoodApps</strong> es solo la empresa desarrolladora y operadora (contratos, consola de plataforma, encargos legales de datos). Debe ser tan completa que un equipo, o Cursor IA trabajando por <strong>olas</strong>, pueda desarrollar todo el sistema <strong>sin consultar otra fuente</strong>. Por eso cada anexo:</p><ul><li>transcribe y consolida (no resume a la ligera) todo requisito, regla, dato, pantalla, parámetro y caso de uso de las fuentes de su ámbito;</li><li>resuelve las contraposiciones entre fuentes según la jerarquía de prevalencia (sección 3) y lo deja escrito;</li><li>convierte cada duda en una <strong>pregunta abierta</strong> con opciones y respuesta recomendada (sección 9).</li></ul><p><strong>Regla de oro: no se pierde ni una línea de información.</strong> Si un dato de la fuente no tiene lugar obvio, va igual al anexo (en &quot;Notas y material adicional&quot;) y se registra en la trazabilidad. Si una función legacy se decide <strong>no</strong> replicar, se registra igualmente con su motivo (estado <code>Descartado</code> o <code>Reemplazado por</code>).</p><h2 id="_2-fuentes-rutas-relativas-a-c-users-lenovo-documents-gacac" tabindex="-1">2. Fuentes (rutas relativas a <code>c:\\Users\\lenovo\\Documents\\GACAC\\</code>) <a class="header-anchor" href="#_2-fuentes-rutas-relativas-a-c-users-lenovo-documents-gacac" aria-label="Permalink to &quot;2. Fuentes (rutas relativas a \`c:\\Users\\lenovo\\Documents\\GACAC\\\`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Código</th><th>Fuente</th><th>Rol</th></tr></thead><tbody><tr><td><strong>BASE</strong></td><td><code>docs/base-funcional/PROCOOP_RELEVAMIENTO_Y_BASE_FUNCIONAL.md</code> (v0.17, secciones 1–107)</td><td><strong>Esqueleto rector.</strong> Requisitos informados por el solicitante y propuestas validadas.</td></tr><tr><td><strong>AGR</strong></td><td><code>docs/base-funcional/PROCOOP_COMPLEMENTO_ANALISIS_FUNCIONAL_Y_DISENO.md</code> (AGR-001 a AGR-036; también integrado en BASE §102)</td><td>Complemento de diseño: bordes, estados, invariantes.</td></tr><tr><td><strong>CNX</strong></td><td><code>referencia-connectia/connectia-referencia-para-goodapps.md</code></td><td><strong>Formato técnico y UI/UX</strong>: stack, layouts, design system, permisos, muro, novedades, encuestas, offline, BI.</td></tr><tr><td><strong>DFA</strong></td><td><code>procoop-relevamiento/definicion-funcional-alcance.md</code> (módulos 1–29)</td><td>Benchmark funcional de ProCoop por pantallas y tablas.</td></tr><tr><td><strong>FIC</strong></td><td><code>procoop-relevamiento/integraciones-fichas.md</code> (fichas 1–23)</td><td>Integraciones externas.</td></tr><tr><td><strong>RN-01…RN-13</strong></td><td><code>procoop-relevamiento/reglas-negocio/NN-*.md</code></td><td>Reglas de negocio extraídas del código de ProCoop, con parámetros <code>Busca_V2_*</code>.</td></tr><tr><td><strong>CAT</strong></td><td><code>procoop-relevamiento/binarios/Procoop-catalogo-tablas.md</code> (659 tablas en 31 módulos)</td><td>Modelo de datos legacy testigo.</td></tr><tr><td><strong>INV</strong></td><td><code>procoop-relevamiento/binarios/inventarios/ProMod_*.md</code>, <code>Configuracion.md</code>, <code>AutoGestion.md</code>, <code>ProcoopNet.md</code></td><td>Inventario de formularios (pantallas) y métodos de ProCoop. Sirve para verificar cobertura de funciones.</td></tr><tr><td><strong>REL</strong></td><td><code>procoop-relevamiento/README.md</code></td><td>Relevamiento por pantallas de la DEMO (menú completo, fichas, comprobantes).</td></tr></tbody></table><p>No se citan ni copian contraseñas, tokens ni código fuente de terceros. Los datos personales de la DEMO no se transcriben (usar datos ficticios).</p><h2 id="_3-jerarquia-de-prevalencia-ante-contraposiciones" tabindex="-1">3. Jerarquía de prevalencia ante contraposiciones <a class="header-anchor" href="#_3-jerarquia-de-prevalencia-ante-contraposiciones" aria-label="Permalink to &quot;3. Jerarquía de prevalencia ante contraposiciones&quot;">​</a></h2><ol><li><strong>Decisiones rectoras DEC-xxx</strong> del documento maestro (<code>00-ESPECIFICACION-MAESTRA.md</code> §3). Son decisiones del solicitante y prevalecen sobre todo.</li><li><strong>BASE</strong>, en su redacción más reciente (las secciones posteriores que declaran &quot;prevalece&quot; sustituyen a las anteriores; ej. §103 prevalece sobre las frases que excluían factura multiservicio; §104 amplía §28).</li><li><strong>AGR</strong> (propuestas del complemento): se adoptan como requisito salvo que contradigan 1 o 2.</li><li><strong>CNX</strong> para todo lo técnico, de UI/UX, layout, componentes, permisos y comunidad.</li><li><strong>DFA, FIC, RN, CAT, INV, REL</strong>: benchmark del sistema a reemplazar. Todo lo que ProCoop hace <strong>entra en el alcance</strong> (decisión DEC-007) salvo que 1–4 lo contradigan o sea una deuda técnica/seguridad de ProCoop (ej. contraseñas reversibles, una base por cooperativa, sincronización con MySQL externa), en cuyo caso se registra como <code>Reemplazado por</code> con la mejora.</li></ol><p>Cada contraposición encontrada se documenta en el anexo, en la sección &quot;Contraposiciones resueltas&quot;, con: fuentes en conflicto, qué dice cada una, resolución aplicada y regla de prevalencia usada. Si la resolución no es evidente, se convierte en <strong>pregunta abierta</strong>.</p><h2 id="_4-decisiones-rectoras-vigentes-resumen-detalle-en-el-maestro" tabindex="-1">4. Decisiones rectoras vigentes (resumen; detalle en el maestro) <a class="header-anchor" href="#_4-decisiones-rectoras-vigentes-resumen-detalle-en-el-maestro" aria-label="Permalink to &quot;4. Decisiones rectoras vigentes (resumen; detalle en el maestro)&quot;">​</a></h2><p><strong>Implementación (DIR-13):</strong> para redactar o exportar al repo GoodApps, usar solo la columna <strong>Vigente (build)</strong>. La columna <strong>Histórico (04-11)</strong> conserva el acuerdo original; no contradecir su <em>funcional</em>.</p><table tabindex="0"><thead><tr><th>ID</th><th>Histórico (04-11)</th><th>Vigente (build, DEC-110–113, 117–118)</th></tr></thead><tbody><tr><td>Stack</td><td>DEC-001: Node + Express + Mongo + Mongoose + Vue (Connectia)</td><td><strong>DEC-111</strong>: .NET 10, ASP.NET Core, EF Core, <strong>Azure SQL</strong>, React 19, Vite, TypeScript, Tailwind; ver maestro §5</td></tr><tr><td>Multitenancy</td><td>DEC-002: base compartida, <code>tenantId</code> en cada documento</td><td><strong>DEC-110</strong>: base compartida Azure SQL, <strong><code>TenantId</code></strong> en tablas de negocio, filtro en EF, índices compuestos; tenant <code>PLATFORM</code></td></tr><tr><td>Arquitectura</td><td>DEC-003: monolito modular + outbox + workers</td><td>Igual (<strong>DEC-003</strong>); colas <strong>Azure Queue</strong> + workers .NET</td></tr><tr><td>Despliegue</td><td>DEC-004: Docker agnóstico; AWS referencia</td><td><strong>DEC-112</strong>: <strong>Microsoft Azure</strong> (Container Apps, Blob, Queue, Key Vault)</td></tr><tr><td>DEC-005–010</td><td>Sin cambio de negocio</td><td>Sin cambio; plan <code>03</code> = mapa de olas (<strong>DEC-118</strong>, no guía de build)</td></tr></tbody></table><h2 id="_4b-guia-ui-ux-para-desarrollo" tabindex="-1">4b. Guía UI/UX para desarrollo <a class="header-anchor" href="#_4b-guia-ui-ux-para-desarrollo" aria-label="Permalink to &quot;4b. Guía UI/UX para desarrollo&quot;">​</a></h2><p>Cualquier pantalla descrita en un anexo debe ser implementable siguiendo <strong><code>GUIA-UI-UX-DESARROLLO.md</code></strong> (checklist <code>PAN-*</code>, shells, componentes de T03 §10.2, diccionario, <code>ScreenHelp</code>). Al redactar filas de la sección Pantallas, indicar <code>screenId</code>, capability de ver y layout (admin / PWA / landing); no prescribir componentes que contradigan T03.</p><h2 id="_5-convenciones-tecnicas-obligatorias-para-todos-los-anexos" tabindex="-1">5. Convenciones técnicas obligatorias para todos los anexos <a class="header-anchor" href="#_5-convenciones-tecnicas-obligatorias-para-todos-los-anexos" aria-label="Permalink to &quot;5. Convenciones técnicas obligatorias para todos los anexos&quot;">​</a></h2><ul><li><strong>Idioma</strong>: español rioplatense neutro. Nombres de <strong>entidades lógicas</strong> (en anexos aún «colecciones»), propiedades y endpoints en <strong>inglés camelCase</strong> en API JSON; en base: tablas/columnas según <code>07-modelo-relacional-azure-sql.md</code> (habitualmente PascalCase en SQL, mapeo EF). Etiquetas de UI en español y <strong>siempre por clave de diccionario</strong> (<code>dict:&amp;lt;clave&gt;</code>), nunca texto fijo (BASE §65).</li><li><strong>Entidades / tablas</strong>: nombre lógico en plural camelCase (<code>accounts</code>, <code>serviceContracts</code>); físico en esquema del módulo (<code>per.Accounts</code>, etc., catálogo <code>07-catalogo-tablas-sql.md</code>). Toda fila de negocio: <code>TenantId</code>, auditoría (<code>CreatedAt</code>, <code>UpdatedAt</code>, <code>CreatedBy</code>, <code>UpdatedBy</code>), <code>Version</code> (concurrencia optimista), y cuando corresponda <code>Status</code>, vigencias, <code>RecordedAt</code> (AGR-010), baja lógica donde aplique; los documentos económicos <strong>nunca</strong> se borran: se anulan o revierten (T05 §7.1.6).</li><li><strong>Dinero</strong>: tipo <strong><code>decimal</code></strong> en SQL (precision/scale por concepto en <code>07</code>); en API y UI, aritmética con biblioteca decimal en .NET/TypeScript; <strong>prohibido float/double para importes</strong>. Precisión por concepto (AGR-011). Moneda <code>ARS</code> por defecto, campo <code>Currency</code>.</li><li><strong>Fechas</strong>: guardadas en UTC; zona horaria del tenant (<code>America/Argentina/Cordoba</code> por defecto) para calendarios, vencimientos y cortes (AGR-017). Formato visible <code>dd-mm-yyyy</code> (CNX).</li><li><strong>Permisos (capabilities)</strong>: <code>modulo.recurso.accion</code>, ej. <code>fac.lotes.aprobar</code>. Acciones estándar: <code>ver</code>, <code>crear</code>, <code>editar</code>, <code>anular</code>, <code>aprobar</code>, <code>exportar</code>, <code>configurar</code>, más las propias. Además del permiso, el <strong>alcance</strong> (<code>scope</code>) sobre datos: tenant / sucursales / zonas / servicios / cuadrillas / propios (CNX §2.4 adaptado).</li><li><strong>API REST</strong>: <code>/api/&amp;lt;modulo&gt;/&amp;lt;recurso&gt;</code> (PWA/socio) y <code>/api/admin/&amp;lt;modulo&gt;/&amp;lt;recurso&gt;</code> (admin), <code>/api/platform/...</code> (plataforma), <code>/api/public/&amp;lt;tenantSlug&gt;/...</code> (landing sin login), <code>/api/v1/ext/...</code> (APIs de terceros con token). Paginación <code>?page=&amp;size=</code> → <code>{ items, total, page, size }</code>. Errores RFC 9457 (<code>application/problem+json</code>) con <code>requestId</code>. Validación Zod compartida. Idempotencia con header <code>Idempotency-Key</code> en toda operación económica o de integración (AGR-016).</li><li><strong>Eventos</strong>: <code>&amp;lt;modulo&gt;.&amp;lt;entidad&gt;.&amp;lt;hecho-en-pasado&gt;</code>, ej. <code>fac.invoice.issued</code>, <code>cob.payment.confirmed</code>. Se publican vía outbox en la misma transacción que el cambio.</li><li><strong>Jobs</strong>: nombre <code>&amp;lt;modulo&gt;:&amp;lt;proceso&gt;</code>, ej. <code>fac:emitir-lote</code>. Cada job es idempotente, reanudable y registra progreso.</li><li><strong>IDs de documentación</strong> (estables, nunca se reutilizan): <ul><li>Requisito funcional: <code>RF-&amp;lt;COD&gt;-NNN</code> · Regla de negocio: <code>RN-&amp;lt;COD&gt;-NNN</code> · Requisito no funcional: <code>RNF-&amp;lt;COD&gt;-NNN</code></li><li>Caso de uso: <code>CU-&amp;lt;COD&gt;-NN</code> · Pantalla: <code>PAN-&amp;lt;COD&gt;-NN</code> · Endpoint: <code>API-&amp;lt;COD&gt;-NN</code> · Evento: <code>EVT-&amp;lt;COD&gt;-NN</code> · Job: <code>JOB-&amp;lt;COD&gt;-NN</code></li><li>Parámetro de configuración: <code>PRM-&amp;lt;COD&gt;-NNN</code> · Pregunta abierta: <code>PA-&amp;lt;COD&gt;-NN</code> · Contraposición: <code>CTR-&amp;lt;COD&gt;-NN</code></li><li>Se conservan siempre los IDs de origen en la columna <strong>Origen</strong> (ej. <code>BASE §103 FAC-006</code>, <code>AGR-012</code>, <code>MER-007</code>, <code>SUE-005</code>, <code>RN-04 §4</code>, <code>DFA M11</code>, <code>FIC 4.1</code>, <code>CAT ENTIDADES</code>, <code>V2 #74</code>, <code>INV frmCierreDiario</code>).</li></ul></li><li><strong>Prioridad dentro del alcance</strong>: <code>Núcleo</code> (sin esto el flujo no funciona), <code>Estándar</code> (necesario para reemplazar ProCoop), <code>Extensión</code> (diferible). Más la <strong>ola</strong> asignada (sección 7).</li><li><strong>Estado del requisito</strong>: <code>Informado</code> (lo pidió el solicitante), <code>Adoptado</code> (propuesta AGR/benchmark aceptada en esta especificación), <code>A validar</code> (depende de una pregunta abierta), <code>Reemplazado por &amp;lt;ID&gt;</code>, <code>Descartado (motivo)</code>.</li></ul><h3 id="codigos-de-anexo" tabindex="-1">Códigos de anexo <a class="header-anchor" href="#codigos-de-anexo" aria-label="Permalink to &quot;Códigos de anexo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Código</th><th>Anexo</th><th>Archivo</th></tr></thead><tbody><tr><td>PLA</td><td>T01 Plataforma SaaS, tenants, licencias, soporte, ambientes, backups</td><td><code>anexos/T01-PLA-plataforma-saas.md</code></td></tr><tr><td>IAM</td><td>T02 Identidad, autenticación, roles, perfiles, alcance, auditoría</td><td><code>anexos/T02-IAM-identidad-roles-auditoria.md</code></td></tr><tr><td>UXD</td><td>T03 UI/UX, design system, marca, diccionario, layouts, mapa del sitio</td><td><code>anexos/T03-UXD-experiencia-marca-diccionario.md</code></td></tr><tr><td>CFG</td><td>T04 Configuración versionada, parámetros, tablas maestras, geografía</td><td><code>anexos/T04-CFG-configuracion-parametros-maestros.md</code> (+ <code>T04b-CFG-catalogo-parametros-procoop.md</code>)</td></tr><tr><td>DAT</td><td>T05 Modelo de datos canónico y responsables</td><td><code>anexos/T05-DAT-modelo-datos.md</code></td></tr><tr><td>INT</td><td>T06 Marco de integraciones y fichas</td><td><code>anexos/T06-INT-integraciones.md</code></td></tr><tr><td>MIG</td><td>T07 Migración, paralelo y by-pass de ProCoop</td><td><code>anexos/T07-MIG-migracion-procoop.md</code></td></tr><tr><td>NFR</td><td>T08 No funcionales, seguridad, privacidad, pruebas, ambientes</td><td><code>anexos/T08-NFR-no-funcionales-seguridad.md</code></td></tr><tr><td>COM</td><td>T09 Comunidad y comunicaciones (muro, novedades, encuestas, notificaciones, audiencia)</td><td><code>anexos/T09-COM-comunidad-comunicaciones.md</code></td></tr><tr><td>BIA</td><td>T10 Reportes, BI, tableros y APIs para terceros</td><td><code>anexos/T10-BIA-reportes-bi-apis.md</code></td></tr><tr><td>WFL</td><td>T11 Workflow, estados, eventos, jobs, autorizaciones, expediente documental</td><td><code>anexos/T11-WFL-workflow-eventos-documentos.md</code></td></tr><tr><td>SRV</td><td>T12 Fichas verticales por servicio (INT, TEL, TV, ELE, AG, CLO, GAS, ALU, OBR, SEP, CEM, SAN, SAL, VIV, TAS, CAP, OTR): recorrido extremo a extremo con referencias a IDs de cada anexo (DEC-073)</td><td><code>anexos/T12-SRV-fichas-verticales-servicios-parte1.md</code> (INT, TEL, TV, ELE, AG, CLO, GAS, ALU y huecos transversales) y <code>anexos/T12-SRV-fichas-verticales-servicios-parte2.md</code> (OBR, SEP, CEM, SAN, SAL, VIV, TAS, CAP, OTR)</td></tr><tr><td>PER</td><td>M01 Personas, titulares, asociados, cuentas, inmuebles, domicilios</td><td><code>anexos/M01-PER-personas-titulares-cuentas.md</code></td></tr><tr><td>CAT</td><td>M02 Catálogo de servicios, productos, planes, categorías, particularidades por servicio</td><td><code>anexos/M02-CAT-catalogo-servicios.md</code></td></tr><tr><td>MED</td><td>M03 Medidores, lecturas, consumos, telemedición, prepago</td><td><code>anexos/M03-MED-medicion-consumos.md</code></td></tr><tr><td>TAR</td><td>M04 Tarifas y motor de cálculo</td><td><code>anexos/M04-TAR-tarifas-motor-calculo.md</code></td></tr><tr><td>FAC</td><td>M05 Facturación, ciclos, lotes y comprobantes</td><td><code>anexos/M05-FAC-facturacion.md</code></td></tr><tr><td>FIS</td><td>M06 Fiscal e impuestos (ARCA, IVA, percepciones, retenciones, regímenes, terceros, reguladores)</td><td><code>anexos/M06-FIS-fiscal-impuestos.md</code></td></tr><tr><td>COB</td><td>M07 Cuenta corriente, cobranza, cajas, entes, débitos, pasarelas, conciliación</td><td><code>anexos/M07-COB-cuenta-corriente-cobranza.md</code></td></tr><tr><td>MOR</td><td>M08 Mora, intereses, suspensión, corte, reconexión, financiación, garantías, incobrables</td><td><code>anexos/M08-MOR-mora-financiacion.md</code></td></tr><tr><td>CRM</td><td>M09 CRM y atención (solicitudes, reclamos, tickets, mesa de entradas, turnero, canales, bot, IA, actividades internas)</td><td><code>anexos/M09-CRM-atencion.md</code></td></tr><tr><td>TEC</td><td>M10 Técnica, campo, agenda, instalación, GIS/redes, obras, aprovisionamiento TIC, telefonía</td><td><code>anexos/M10-TEC-tecnica-campo-redes.md</code></td></tr><tr><td>VEN</td><td>M11 Ventas, presupuestos, POS</td><td><code>anexos/M11-VEN-ventas-presupuestos.md</code></td></tr><tr><td>CMP</td><td>M12 Compras y proveedores</td><td><code>anexos/M12-CMP-compras-proveedores.md</code></td></tr><tr><td>STK</td><td>M13 Stock, equipos serializados, bienes de uso, RMA, fabricación</td><td><code>anexos/M13-STK-stock-activos-fabricacion.md</code></td></tr><tr><td>TES</td><td>M14 Tesorería y bancos</td><td><code>anexos/M14-TES-tesoreria-bancos.md</code></td></tr><tr><td>CON</td><td>M15 Contabilidad, centros de costo, planes múltiples, presupuestos</td><td><code>anexos/M15-CON-contabilidad.md</code></td></tr><tr><td>SUE</td><td>M16 Personal y sueldos</td><td><code>anexos/M16-SUE-personal-sueldos.md</code></td></tr><tr><td>INS</td><td>M17 Gestión institucional (asociados, capital, asambleas, consejo, INAES)</td><td><code>anexos/M17-INS-institucional.md</code></td></tr><tr><td>SOC</td><td>M18 Servicios sociales y otros (vivienda, salud/ambulancias, sepelio, cementerio parque, banco de sangre), flota y traslados</td><td><code>anexos/M18-SOC-servicios-sociales-flota.md</code></td></tr><tr><td>POR</td><td>M19 Landing, portal y app del socio (autogestión)</td><td><code>anexos/M19-POR-portal-socio-landing.md</code></td></tr></tbody></table><h2 id="_6-plantilla-obligatoria-de-cada-anexo-de-modulo" tabindex="-1">6. Plantilla obligatoria de cada anexo de módulo <a class="header-anchor" href="#_6-plantilla-obligatoria-de-cada-anexo-de-modulo" aria-label="Permalink to &quot;6. Plantilla obligatoria de cada anexo de módulo&quot;">​</a></h2><p>Usar exactamente estos títulos y este orden (los transversales pueden adaptar 7–15 a su naturaleza, manteniendo 1–6 y 16–22):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># &lt;Código anexo&gt; &lt;COD&gt; — &lt;Nombre&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| Campo | Valor |</span></span>
<span class="line"><span>|---|---|</span></span>
<span class="line"><span>| Versión | 1.0 |</span></span>
<span class="line"><span>| Estado | Especificación consolidada — pendiente de validar preguntas abiertas |</span></span>
<span class="line"><span>| Solución (BASE §105) | ERP / CRM / Landing-autogestión / Plataforma / Cobranza / Pasarelas / Impuestos / APIs |</span></span>
<span class="line"><span>| Olas | O&lt;n&gt;… |</span></span>
<span class="line"><span>| Dueño de datos | qué entidades son propiedad de este módulo |</span></span>
<span class="line"><span>| Fuentes consolidadas | lista exacta de secciones (BASE §x, AGR-xxx, DFA Mx, FIC x, RN-xx §y, CAT §n, V2 módulo, INV archivos, CNX §z) |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 1. Objetivo</span></span>
<span class="line"><span>## 2. Límite y responsabilidades (qué hace, qué NO hace, qué delega y a quién)</span></span>
<span class="line"><span>## 3. Glosario del módulo (término, definición, clave de diccionario, término ProCoop equivalente)</span></span>
<span class="line"><span>## 4. Actores, permisos y alcance (tabla: rol, capabilities \`cod.recurso.accion\`, alcance de datos)</span></span>
<span class="line"><span>## 5. Requisitos funcionales (tabla: ID | Requisito | Origen | Prioridad | Ola | Estado | Criterio de aceptación)</span></span>
<span class="line"><span>## 6. Reglas de negocio (tabla o fichas: ID | Regla | Comportamiento ProCoop (fuente) | Decisión en CoopApps: Replicar / Mejorar / Reemplazar / Descartar | Parámetros | [VERIFICAR] si aplica)</span></span>
<span class="line"><span>## 7. Modelo de datos (por colección: propósito, campos con tipo y obligatoriedad, enums, índices, vigencias, relaciones; mapeo a tablas ProCoop origen)</span></span>
<span class="line"><span>## 8. Estados y transiciones (por entidad: estado origen → destino, actor, precondición, efectos, reversión — AGR-003)</span></span>
<span class="line"><span>## 9. Procesos y flujos (paso a paso, incluidos batch/jobs JOB-xxx, reintentos, cancelación, recuperación)</span></span>
<span class="line"><span>## 10. Pantallas (por pantalla: PAN-ID, app [admin|pwa-socio|pwa-empleado|pwa-campo|landing|plataforma], ruta, capability, propósito, layout CNX, filtros, columnas/campos, acciones, modales, estados vacíos, ayuda contextual; equivalencia con formularios ProCoop INV)</span></span>
<span class="line"><span>## 11. API (tabla: API-ID | Método | Ruta | Capability | Descripción | Idempotente)</span></span>
<span class="line"><span>## 12. Eventos y jobs (emitidos, consumidos, jobs batch con frecuencia)</span></span>
<span class="line"><span>## 13. Integraciones (referencia a T06 y particularidades del módulo)</span></span>
<span class="line"><span>## 14. Parámetros de configuración (tabla: PRM-ID | Clave | Tipo | Ámbito: plataforma/tenant/servicio/categoría | Default | Descripción | Origen V2 #n)</span></span>
<span class="line"><span>## 15. Reportes, indicadores y exportaciones (fórmula, universo, fecha de corte — AGR-022)</span></span>
<span class="line"><span>## 16. Casos de uso (CU originales de BASE con su ID original + nuevos)</span></span>
<span class="line"><span>## 17. Criterios de aceptación y escenarios de prueba (incluye permisos negativos, aislamiento de tenant, reintentos, conciliación; ESC-01..05 cuando apliquen)</span></span>
<span class="line"><span>## 18. Datos de precarga de demostración (ficticios)</span></span>
<span class="line"><span>## 19. Migración desde ProCoop (tabla origen → colección destino, transformación, validación de conciliación)</span></span>
<span class="line"><span>## 20. Contraposiciones resueltas (CTR-ID | Fuentes | Conflicto | Resolución | Regla de prevalencia)</span></span>
<span class="line"><span>## 21. Preguntas abiertas (formato de la sección 9 de esta guía)</span></span>
<span class="line"><span>## 22. Trazabilidad de fuentes (checklist: cada sección/regla/tabla/formulario/parámetro de la fuente → ID(s) de este anexo donde quedó, o \`Descartado: motivo\`)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br></div></div><h2 id="_7-olas-asignar-cada-requisito-a-una" tabindex="-1">7. Olas (asignar cada requisito a una) <a class="header-anchor" href="#_7-olas-asignar-cada-requisito-a-una" aria-label="Permalink to &quot;7. Olas (asignar cada requisito a una)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ola</th><th>Contenido</th></tr></thead><tbody><tr><td>O0</td><td>Fundaciones: monorepo, Docker, CI, convenciones, librerías compartidas (money, fechas, Zod), shells AdminShell/AppShell, design system, DataTable, ExcelImportWizard, toasts/confirm, auth básica, tenancy plugin, auditoría genérica, outbox + BullMQ, almacenamiento privado, diccionario y branding base, notificaciones base.</td></tr><tr><td>O1</td><td>Plataforma SaaS e IAM completos: tenants y ciclo de vida, licencias/capabilities, roles/perfiles/alcance, usuarios, 2FA, Google, soporte con acceso temporal, configuración versionada y publicación, parámetros, tablas maestras, geografía/calles, workflow de autorizaciones, expediente documental.</td></tr><tr><td>O2</td><td>Personas/titulares/cuentas/inmuebles, catálogo de servicios/productos/planes, habilitación por tenant, copia de servicios entre tenants, landing pública, registro y portal base del socio, CRM de solicitudes (alta/baja), comunidad (muro, novedades, encuestas, centro de comunicaciones).</td></tr><tr><td>O3</td><td>Técnica para el piloto Internet: factibilidad, agenda y visitas, órdenes de trabajo, instalación integral (equipo en comodato, firma, encuesta), stock serializado de equipos, app de campo offline, aprovisionamiento de Internet (MikroTik/Radius/OLT).</td></tr><tr><td>O4</td><td>Motor tarifario (P×Q, fijos, planes, prorrateos, promociones) + facturación (ciclos, lotes, separada/agrupada, numeración, vencimientos, anulación/NC/ND, PDF, QR, código de barras, distribución) + ARCA (WSAA/WSFEv1, CAE/CAEA, padrón) + impuestos básicos (IVA, percepciones IIBB, tasas de terceros).</td></tr><tr><td>O5</td><td>Cuenta corriente (auxiliar, imputación, saldos a favor, no identificados), cobranza en caja, pasarelas (Pagos360, Mercado Pago, SIRO, otros), redes (Red Link, SIRO), débitos automáticos, conciliación, devoluciones/contracargos; <strong>núcleo contable</strong> (plan de cuentas, ejercicios, centros de costo, asientos automáticos).</td></tr><tr><td>O6</td><td>Mora (intereses, recargos, instancias, notificaciones), suspensión/corte/reconexión integrados con técnica y aprovisionamiento, convenios y planes de pago, garantías, incobrables, gestión judicial. <strong>Cierre del piloto Internet extremo a extremo.</strong></td></tr><tr><td>O7</td><td>Servicios medidos: medidores, rutas, app de lecturas, validación de consumos, estimaciones, telemedición, prepago; tarifas medidas (tramos, demanda, factor de potencia, cargos adicionales con fórmulas, prorrateo entre cuadros), electricidad, agua, gas, generación distribuida, grandes usuarios, subsidios/segmentación/tarifa social, reguladores (ERSeP, ENARGAS, ENACOM, Secretaría de Energía), compra de energía (EPEC).</td></tr><tr><td>O8</td><td>ERP administrativo: compras, proveedores, retenciones, stock completo, bienes de uso, RMA, tesorería y bancos, Interbanking, valores, contabilidad completa (cierres, balances, INAES, múltiples planes y simulaciones), presupuestos, regímenes informativos (CITI/RG3685, SICORE, SIRCAR, libros IVA digitales).</td></tr><tr><td>O9</td><td>Personal y sueldos (legajos, liquidaciones, SAC, Ganancias, F.931, LSD, recibos, portal del empleado, RRHH GLM).</td></tr><tr><td>O10</td><td>Institucional (asociados, capital, asambleas, consejo, actas, INAES), servicios sociales (sepelio, cementerio parque, banco de sangre, salud/ambulancias, planes de vivienda), flota y traslados (GPS), telefonía (centrales, CDR, tasación), TV/otros TIC, fabricación, turnero y agente de hardware local, actividades internas.</td></tr><tr><td>O11</td><td>Reportes avanzados, BI (salas, cubos certificados, IA), generador de reportes del tenant, APIs para terceros, migración repetible desde ProCoop, paralelo factura por factura y by-pass.</td></tr></tbody></table><p>Si un requisito de un módulo de ola tardía es prerrequisito de una ola anterior, se asigna a la ola anterior (ej. stock serializado de equipos en O3 aunque stock completo sea O8).</p><h2 id="_8-pantallas-patron-connectia-obligatorio" tabindex="-1">8. Pantallas: patrón Connectia obligatorio <a class="header-anchor" href="#_8-pantallas-patron-connectia-obligatorio" aria-label="Permalink to &quot;8. Pantallas: patrón Connectia obligatorio&quot;">​</a></h2><ul><li><strong>Admin web</strong> (<code>apps/admin</code>): AdminShell con topbar (logo producto, logo tenant, selector de contexto, Mapa del sitio, accesos fijados), menú declarativo único <code>siteMapGroups</code> (clusters → grupos → ítems con capability), <code>AdminStickyHeader</code> (título, subtítulo, acciones), <code>ScreenHelp</code> (qué/quién/cuándo/dónde/por qué/cómo + caso de uso), <code>DataTable</code> genérico (columnas configurables, orden, filtros, paginación, exportar XLSX/CSV/PDF, selección masiva, vistas guardadas), modales <code>sm/md/lg/xl</code>, <code>ExcelImportWizard</code> (subir → preview con errores → confirmar), toasts y <code>ConfirmDialog</code>, previews &quot;celular&quot;, IA solo propone. Tema oscuro por defecto con tokens CNX §4.1; tipografías Space Grotesk / IBM Plex Sans / IBM Plex Mono (importes y lecturas).</li><li><strong>PWA</strong> (<code>apps/pwa</code>, una sola app con landing por rol: socio, empleado, técnico, lecturista, cobrador): AppShell (topbar, banners, contenido, tabbar con FAB &quot;+&quot;), piel oscura <code>.pwa-mod</code> con tokens CNX §3.1, branding runtime por tenant, manifest dinámico, cards de listado con anatomía fija, alta siempre en modal desde FAB, 3 skeleton cards, errores inline, offline con cola única IndexedDB + <code>clientMutationId</code>.</li><li><strong>Landing</strong> (<code>apps/landing</code> o rutas públicas): marca, noticias, servicios habilitados, registro, consulta pública, pago sin login cuando aplique, baja pública cuando corresponda (BASE §53).</li><li><strong>Plataforma</strong> (rutas <code>meta.platformOnly</code> en admin): tenants, licencias, soporte, salud, dashboards globales.</li><li>Cada pantalla se especifica con PAN-ID y se mapea a los formularios ProCoop que reemplaza (INV) para asegurar cobertura.</li></ul><h2 id="_9-formato-de-preguntas-abiertas" tabindex="-1">9. Formato de preguntas abiertas <a class="header-anchor" href="#_9-formato-de-preguntas-abiertas" aria-label="Permalink to &quot;9. Formato de preguntas abiertas&quot;">​</a></h2><p>Cada duda real (no resoluble con la jerarquía de la sección 3) se escribe así, para luego presentarse al solicitante en formato interactivo de opción múltiple:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### PA-&lt;COD&gt;-NN — &lt;título corto&gt;</span></span>
<span class="line"><span>- **Pregunta:** &lt;redacción clara, una sola decisión&gt;</span></span>
<span class="line"><span>- **Contexto:** &lt;por qué importa, qué fuentes chocan o qué falta&gt;</span></span>
<span class="line"><span>- **Opciones:**</span></span>
<span class="line"><span>  - A) &lt;opción&gt; **(Recomendada)** — &lt;consecuencia&gt;</span></span>
<span class="line"><span>  - B) &lt;opción&gt; — &lt;consecuencia&gt;</span></span>
<span class="line"><span>  - C) &lt;opción&gt; — &lt;consecuencia&gt;</span></span>
<span class="line"><span>- **Impacto si no se responde:** &lt;qué se asume por defecto; siempre se asume la Recomendada&gt;</span></span>
<span class="line"><span>- **Bloquea:** &lt;IDs de requisitos/olas afectados&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Mientras no se responda, el anexo <strong>asume la opción recomendada</strong> y marca los requisitos afectados como <code>A validar (PA-xxx)</code>. Las preguntas deben ser de decisión del solicitante (negocio, alcance, prioridad, política); no preguntar lo que ya está resuelto por fuentes o por las DEC.</p><h2 id="_10-calidad-minima-exigida" tabindex="-1">10. Calidad mínima exigida <a class="header-anchor" href="#_10-calidad-minima-exigida" aria-label="Permalink to &quot;10. Calidad mínima exigida&quot;">​</a></h2><ul><li>Cada anexo de módulo debe tener, como orden de magnitud, decenas de RF y RN (los módulos grandes, más de 60–100), todas las colecciones con campos, todas las pantallas del módulo y todos los formularios ProCoop relevantes mapeados.</li><li>Nada de &quot;etc.&quot;, &quot;entre otros&quot; o &quot;similares&quot; sin enumerar: si la fuente enumera, se enumera todo.</li><li>Los ejemplos numéricos son ficticios y en ARS.</li><li>La sección 22 (trazabilidad) es la prueba de exhaustividad: debe listar <strong>cada</strong> sección de BASE, AGR, DFA, FIC, RN, CAT e INV asignada al anexo, con su destino.</li></ul>`,35)])])}const g=a(t,[["render",d]]);export{m as __pageData,g as default};
